 32	namespace TutorFlow.Api;
 33	
 34	public sealed partial class ProcesadorPregunta
 35	{
 36	    private const string TituloSolicitudInvalida = "La solicitud no es válida.";
 37	    private const string TituloCuerpoDemasiadoGrande = "El cuerpo de la solicitud supera el tamaño permitido.";
 38	    private const string TituloDemasiadasSolicitudes = "Se superó el límite de preguntas. Intenta de nuevo más tarde.";
 39	    private const string TituloServicioNoDisponible = "El servicio no está disponible en este momento. Intenta de nuevo.";
 40	
 41	    private readonly LimitesAsistente _limites;
 42	    private readonly LimitadorTasaPorIp _limitadorTasa;
 43	    private readonly LimitadorIdentidades _limitadorIdentidades;
 44	    private readonly AuditorPeticiones _auditor;
 45	    private readonly PreguntarAsistente _preguntarAsistente;
 46	    private readonly ILogger<ProcesadorPregunta> _logger;
 47	
 48	    public ProcesadorPregunta(
 49	        LimitesAsistente limites,
 50	        LimitadorTasaPorIp limitadorTasa,
 51	        LimitadorIdentidades limitadorIdentidades,
 52	        AuditorPeticiones auditor,
 53	        PreguntarAsistente preguntarAsistente,
 54	        ILogger<ProcesadorPregunta> logger)
 55	    {
 56	        _limites = limites;
 57	        _limitadorTasa = limitadorTasa;
 58	        _limitadorIdentidades = limitadorIdentidades;
 59	        _auditor = auditor;
 60	        _preguntarAsistente = preguntarAsistente;
 61	        _logger = logger;
 62	    }
 63	
 64	    public async Task<IResult> ProcesarAsync(HttpContext contexto, CancellationToken cancellationToken)
 65	    {
 66	        var peticion = new DatosPeticion(IpDe(contexto), contexto.TraceIdentifier, Stopwatch.StartNew());
 67	        var tasa = _limitadorTasa.Intentar(peticion.Ip);
 68	        if (!tasa.Permitido)
 69	        {
 70	            return Rechazar429(contexto, peticion, null, tasa.SegundosParaReintentar);
 71	        }
 72	
 73	        var cuerpo = await LectorCuerpo.LeerAsync(contexto.Request.Body, _limites.MaximoBytesCuerpo, cancellationToken);
 74	        if (cuerpo.ExcedeElLimite)
 75	        {
 76	            return RechazarInvalida(peticion, null, StatusCodes.Status413PayloadTooLarge, TituloCuerpoDemasiadoGrande);
 77	        }
 78	
 79	        var solicitud = ValidadorSolicitud.Validar(cuerpo.Bytes, _limites.MaximoCaracteresPregunta);
 80	        return solicitud.EsValida
 81	            ? await ResponderAsync(contexto, peticion, solicitud, cancellationToken)
 82	            : RechazarInvalida(peticion, solicitud.Pregunta, StatusCodes.Status400BadRequest, TituloSolicitudInvalida);
 83	    }
 84	
 85	    private static string IpDe(HttpContext contexto)
 86	    {
 87	        var direccion = contexto.Connection.RemoteIpAddress;
 88	        if (direccion is null)
 89	        {
 90	            return "desconocida";
 91	        }
 92	
 93	        return (direccion.IsIPv4MappedToIPv6 ? direccion.MapToIPv4() : direccion).ToString();
 94	    }
 95	
 96	    private async Task<IResult> ResponderAsync(HttpContext contexto, DatosPeticion peticion, SolicitudValidada solicitud, CancellationToken cancellationToken)
 97	    {
 98	        var usuario = new Usuario(solicitud.Rol!.Value, solicitud.UsuarioId!);
 99	        var identidades = _limitadorIdentidades.Registrar(peticion.Ip, usuario.Id);
100	        if (identidades.SuperacionNueva)
101	        {
102	            _auditor.RegistrarMultiplesIdentidades(peticion.Ip, identidades.Ids);
103	        }
104	
105	        if (identidades.Superado && _limites.BloquearMultiplesIdentidades)
106	        {
107	            return Rechazar429(contexto, peticion, solicitud, (int)TimeSpan.FromMinutes(_limites.VentanaIdentidadesMinutos).TotalSeconds);
108	        }
109	
110	        return await PreguntarAsync(peticion, new PreguntaEntrada(solicitud.Pregunta!, usuario), cancellationToken);
111	    }
112	
113	    private async Task<IResult> PreguntarAsync(DatosPeticion peticion, PreguntaEntrada entrada, CancellationToken cancellationToken)
114	    {
115	        try
116	        {
117	            var resultado = await _preguntarAsistente.EjecutarAsync(entrada, peticion.Ip, peticion.CorrelationId, cancellationToken);
118	            return Mapear(resultado);
119	        }
120	        catch (Exception excepcion) when (EsFalloDeDependencia(excepcion, cancellationToken))
121	        {
122	            RegistrarDependenciaCaida(_logger, excepcion.GetType().Name);
123	            RegistrarError(peticion, entrada);
124	            return Results.Problem(statusCode: StatusCodes.Status503ServiceUnavailable, title: TituloServicioNoDisponible);
125	        }
126	        catch (Exception)
127	        {
128	            RegistrarError(peticion, entrada);
129	            throw;
130	        }
131	    }
132	
133	    private static bool EsFalloDeDependencia(Exception excepcion, CancellationToken cancellationToken) =>
134	        excepcion is DependenciaNoDisponibleException or HttpRequestException or TimeoutException
135	        || (excepcion is OperationCanceledException && !cancellationToken.IsCancellationRequested);
136	
137	    private void RegistrarError(DatosPeticion peticion, PreguntaEntrada entrada) =>
138	        _auditor.RegistrarSinConsultas(new SolicitudAuditoria(
139	            peticion.Ip,
140	            peticion.CorrelationId,
141	            entrada.Usuario.Rol,
142	            entrada.Usuario.Id,
143	            entrada.Pregunta,
144	            ResultadoAuditoria.Error,
145	            peticion.Cronometro.ElapsedMilliseconds));
146	
147	    private static IResult Mapear(ResultadoPregunta resultado)
148	    {
149	        if (resultado.Respuesta is not { } respuesta)
150	        {
151	            return Results.Problem(statusCode: StatusCodes.Status503ServiceUnavailable, title: TituloServicioNoDisponible);
152	        }
153	
154	        var cuerpo = new PreguntaRespuesta(
155	            respuesta.Respuesta,
156	            [.. respuesta.Citas.Select(cita => new CitaRespuesta(cita.Documento, cita.Seccion))],
157	            respuesta.UsoDatosEstudiante,
158	            respuesta.Tokens,
159	            respuesta.CostoUsd);
160	        var estado = resultado.Tipo == TipoResultadoPregunta.Denegada ? StatusCodes.Status403Forbidden : StatusCodes.Status200OK;
161	        return Results.Json(cuerpo, statusCode: estado);
162	    }
163	
164	    private IResult RechazarInvalida(DatosPeticion peticion, string? pregunta, int estado, string titulo)
165	    {
166	        _auditor.RegistrarSinConsultas(new SolicitudAuditoria(
167	            peticion.Ip,
168	            peticion.CorrelationId,
169	            null,
170	            null,
171	            pregunta,
172	            ResultadoAuditoria.Invalida,
173	            peticion.Cronometro.ElapsedMilliseconds));
174	        return Results.Problem(statusCode: estado, title: titulo);
175	    }
176	
177	    private IResult Rechazar429(HttpContext contexto, DatosPeticion peticion, SolicitudValidada? solicitud, int segundosParaReintentar)
178	    {
179	        _auditor.RegistrarSinConsultas(new SolicitudAuditoria(
180	            peticion.Ip,
181	            peticion.CorrelationId,
182	            solicitud?.Rol,
183	            solicitud?.UsuarioId,
184	            solicitud?.Pregunta,
185	            ResultadoAuditoria.Denegada,
186	            peticion.Cronometro.ElapsedMilliseconds));
187	        contexto.Response.Headers.RetryAfter = segundosParaReintentar.ToString(System.Globalization.CultureInfo.InvariantCulture);
188	        return Results.Problem(statusCode: StatusCodes.Status429TooManyRequests, title: TituloDemasiadasSolicitudes);
189	    }
190	
191	    [LoggerMessage(Level = LogLevel.Warning, Message = "Una dependencia no respondió ({TipoDeError}).")]
192	    private static partial void RegistrarDependenciaCaida(ILogger logger, string tipoDeError);
193	
194	    private sealed record DatosPeticion(string Ip, string CorrelationId, Stopwatch Cronometro);
195	}
