199	namespace TutorFlow.Api;
200	
201	public sealed record SolicitudValidada(bool EsValida, string? Pregunta, Rol? Rol, string? UsuarioId)
202	{
203	    public static SolicitudValidada Invalida(string? pregunta = null) => new(false, pregunta, null, null);
204	}
205	
206	public static class ValidadorSolicitud
207	{
208	    private const string RolEstudiante = "estudiante";
209	    private const string RolCoordinador = "coordinador";
210	
211	    private static readonly JsonSerializerOptions OpcionesJson = new(JsonSerializerDefaults.Web);
212	
213	    public static SolicitudValidada Validar(byte[] cuerpo, int maximoCaracteresPregunta)
214	    {
215	        var solicitud = Deserializar(cuerpo);
216	        if (solicitud is null)
217	        {
218	            return SolicitudValidada.Invalida();
219	        }
220	
221	        return ValidarCampos(solicitud, maximoCaracteresPregunta);
222	    }
223	
224	    private static SolicitudValidada ValidarCampos(PreguntaSolicitud solicitud, int maximoCaracteresPregunta)
225	    {
226	        var usuario = solicitud.Usuario ?? new UsuarioSolicitud(null, null);
227	        var rol = ConvertirRol(usuario.Rol);
228	        var camposValidos = TieneFormaDeId(usuario.Id) && EsPreguntaValida(solicitud.Pregunta, maximoCaracteresPregunta);
229	        return rol is not null && camposValidos
230	            ? new SolicitudValidada(true, solicitud.Pregunta, rol, usuario.Id)
231	            : SolicitudValidada.Invalida(solicitud.Pregunta);
232	    }
233	
234	    private static PreguntaSolicitud? Deserializar(byte[] cuerpo)
235	    {
236	        try
237	        {
238	            return JsonSerializer.Deserialize<PreguntaSolicitud>(cuerpo, OpcionesJson);
239	        }
240	        catch (JsonException)
241	        {
242	            return null;
243	        }
244	    }
245	
246	    private static Rol? ConvertirRol(string? rol) => rol switch
247	    {
248	        RolEstudiante => Rol.Estudiante,
249	        RolCoordinador => Rol.Coordinador,
250	        _ => null
251	    };
252	
253	    private static bool TieneFormaDeId(string? id) =>
254	        Identificadores.EsIdEstudiante(id) || Identificadores.EsIdCoordinador(id);
255	
256	    private static bool EsPreguntaValida(string? pregunta, int maximo) =>
257	        !string.IsNullOrWhiteSpace(pregunta) && pregunta.Length <= maximo;
258	}
259	namespace TutorFlow.Api;
260	
261	public sealed record CuerpoLeido(bool ExcedeElLimite, byte[] Bytes);
262	
263	public static class LectorCuerpo
264	{
265	    private const int TamanoDeBloque = 4096;
266	
267	    public static async Task<CuerpoLeido> LeerAsync(Stream cuerpo, int maximoBytes, CancellationToken cancellationToken)
268	    {
269	        using var acumulado = new MemoryStream();
270	        var bloque = new byte[TamanoDeBloque];
271	        int leidos;
272	        while ((leidos = await cuerpo.ReadAsync(bloque, cancellationToken)) > 0)
273	        {
274	            acumulado.Write(bloque, 0, leidos);
275	            if (acumulado.Length > maximoBytes)
276	            {
277	                return new CuerpoLeido(true, []);
278	            }
279	        }
280	
281	        return new CuerpoLeido(false, acumulado.ToArray());
282	    }
283	}

