237	public sealed class PoliticaAcceso
238	{
239	    private static readonly DecisionAcceso AccesoPermitido = DecisionAcceso.Permitir();
240	    private readonly DecisionAcceso _decisionPermitida = AccesoPermitido;
241	
242	    public DecisionAcceso EvaluarIdentidad(Usuario usuario, DirectorioAcademico directorio) =>
243	        ExisteIdentidad(usuario, directorio)
244	            ? _decisionPermitida
245	            : DecisionAcceso.Denegar(MotivoDenegacion.IdentidadInvalida);
246	
247	    public DecisionAcceso EvaluarPregunta(Usuario usuario, string pregunta, DirectorioAcademico directorio)
248	    {
249	        var texto = NormalizadorTexto.Normalizar(pregunta);
250	        var motivo = MotivoTercero(usuario, texto, directorio)
251	            ?? MotivoPrograma(usuario, texto, directorio)
252	            ?? MotivoAgregado(usuario, texto);
253	        return motivo is { } denegado ? DecisionAcceso.Denegar(denegado) : DecisionAcceso.Permitir();
254	    }
255	
256	    public DecisionAcceso EvaluarLecturaEstudiante(Usuario usuario, string estudianteId, DirectorioAcademico directorio) =>
257	        PuedeLeerEstudiante(usuario, estudianteId, directorio)
258	            ? DecisionAcceso.Permitir()
259	            : DecisionAcceso.Denegar(MotivoDenegacion.HerramientaIdAjeno);
260	
261	    public IReadOnlyList<string> ProgramasAutorizados(Usuario usuario, DirectorioAcademico directorio) =>
262	        EvaluarIdentidad(usuario, directorio).Permitido ? AmbitoPersonal.ProgramasDe(usuario, directorio) : [];
263	
264	    public IReadOnlyList<string> IdsPersonasAutorizadas(Usuario usuario, DirectorioAcademico directorio)
265	    {
266	        if (!EvaluarIdentidad(usuario, directorio).Permitido)
267	        {
268	            return [];
269	        }
270	
271	        var ambito = AmbitoPersonal.De(usuario, directorio);
272	        return [.. directorio.Estudiantes.Select(e => e.Id)
273	            .Concat(directorio.Coordinadores.Select(c => c.Id))
274	            .Where(id => ambito.ClavesDeNombre.Contains(AmbitoPersonal.Clave(id)))];
275	    }
