277	    private static bool ExisteIdentidad(Usuario usuario, DirectorioAcademico directorio) => usuario.Rol switch
278	    {
279	        Rol.Estudiante => Identificadores.EsIdEstudiante(usuario.Id) && directorio.Estudiantes.Any(e => e.Id == usuario.Id),
280	        Rol.Coordinador => Identificadores.EsIdCoordinador(usuario.Id) && directorio.Coordinadores.Any(c => c.Id == usuario.Id),
281	        _ => false
282	    };
283	
284	    private bool PuedeLeerEstudiante(Usuario usuario, string estudianteId, DirectorioAcademico directorio)
285	    {
286	        var estudiante = directorio.Estudiantes.FirstOrDefault(e => e.Id == estudianteId);
287	        if (estudiante is null || !Identificadores.EsIdEstudiante(estudianteId))
288	        {
289	            return false;
290	        }
291	
292	        return usuario.Rol == Rol.Estudiante
293	            ? usuario.Id == estudianteId
294	            : ProgramasAutorizados(usuario, directorio).Contains(estudiante.ProgramaId);
295	    }
296	
297	    private static MotivoDenegacion? MotivoTercero(Usuario usuario, string texto, DirectorioAcademico directorio) =>
298	        DetectorTerceros.MencionaTercero(usuario, texto, directorio) ? MotivoDenegacion.TerceroMencionado : null;
299	
300	    private MotivoDenegacion? MotivoPrograma(Usuario usuario, string texto, DirectorioAcademico directorio) =>
301	        usuario.Rol == Rol.Coordinador && DetectorProgramas.MencionaProgramaAjeno(texto, ProgramasAutorizados(usuario, directorio), directorio)
302	            ? MotivoDenegacion.ProgramaAjeno
303	            : null;
304	
305	    private static MotivoDenegacion? MotivoAgregado(Usuario usuario, string texto) =>
306	        usuario.Rol == Rol.Estudiante && DetectorAgregados.PideAgregados(texto) ? MotivoDenegacion.Agregado : null;
307	}
