  6	public static class ConstructorDirectorio
  7	{
  8	    public static DirectorioAcademico Vacio { get; } = new([], [], [], []);
  9	
 10	    public static async Task<DirectorioAcademico?> ConstruirAsync(
 11	        Usuario usuario,
 12	        IApiAcademica api,
 13	        IReadOnlyCollection<string> codigosAsignatura,
 14	        CancellationToken cancellationToken)
 15	    {
 16	        var estudiante = usuario.Rol == Rol.Estudiante ? await api.ObtenerEstudianteAsync(usuario.Id, cancellationToken) : null;
 17	        var coordinador = usuario.Rol == Rol.Coordinador ? await api.ObtenerCoordinadorAsync(usuario.Id, cancellationToken) : null;
 18	        if (estudiante is null && coordinador is null)
 19	        {
 20	            return null;
 21	        }
 22	
 23	        var programas = (await api.ObtenerProgramasAsync(cancellationToken)).Where(p => Identificadores.EsIdPrograma(p.Id)).ToList();
 24	        var estudiantes = await LeerEstudiantesAsync(programas, estudiante, api, cancellationToken);
 25	        var coordinadores = await LeerCoordinadoresAsync(programas, coordinador, api, cancellationToken);
 26	        return new DirectorioAcademico(estudiantes, coordinadores, programas, codigosAsignatura);
 27	    }
 28	
 29	    private static async Task<List<Estudiante>> LeerEstudiantesAsync(
 30	        List<Programa> programas,
 31	        Estudiante? propio,
 32	        IApiAcademica api,
 33	        CancellationToken cancellationToken)
 34	    {
 35	        var estudiantes = new List<Estudiante>();
 36	        foreach (var programa in programas)
 37	        {
 38	            estudiantes.AddRange(await api.ObtenerEstudiantesDeProgramaAsync(programa.Id, cancellationToken));
 39	        }
 40	
 41	        if (propio is not null)
 42	        {
 43	            estudiantes.Add(propio);
 44	        }
 45	
 46	        return [.. estudiantes.DistinctBy(e => e.Id)];
 47	    }
 48	
 49	    private static async Task<List<Coordinador>> LeerCoordinadoresAsync(
 50	        List<Programa> programas,
 51	        Coordinador? propio,
 52	        IApiAcademica api,
 53	        CancellationToken cancellationToken)
 54	    {
 55	        var coordinadores = new List<Coordinador>();
 56	        var ids = programas.Select(p => p.CoordinadorId).Where(Identificadores.EsIdCoordinador).Distinct();
 57	        foreach (var id in ids.Where(id => id != propio?.Id))
 58	        {
 59	            var coordinador = await api.ObtenerCoordinadorAsync(id, cancellationToken);
 60	            if (coordinador is not null)
 61	            {
 62	                coordinadores.Add(coordinador);
 63	            }
 64	        }
 65	
 66	        if (propio is not null)
 67	        {
 68	            coordinadores.Add(propio);
 69	        }
 70	
 71	        return coordinadores;
 72	    }
 73	}
