121	        _politicaAcceso = politicaAcceso;
122	        _manejadores = new Dictionary<string, Func<SolicitudHerramienta, Task<ResultadoHerramienta>>>
123	        {
124	            [DatosBasicos] = ConsultarDatosBasicos,
