136	    public async Task<ResultadoHerramienta> EjecutarAsync(
137	        LlamadaHerramienta llamada,
138	        ContextoUsuario contexto,
139	        RegistroConsultas registro,
140	        CancellationToken cancellationToken)
141	    {
142	        if (!EstaDisponible(llamada.Nombre, contexto.Usuario.Rol) || !_manejadores.TryGetValue(llamada.Nombre, out var manejador))
143	        {
144	            return ResultadoHerramienta.Texto("Herramienta no disponible.");
145	        }
146	
147	        var estudianteId = ArgumentosHerramienta.LeerTexto(llamada.ArgumentosJson, ParametroEstudianteId);
148	        if (EsLecturaAjena(contexto, estudianteId))
149	        {
150	            return ResultadoHerramienta.Denegado();
151	        }
152	
153	        var asignatura = ArgumentosHerramienta.LeerTexto(llamada.ArgumentosJson, ParametroAsignatura);
154	        return await manejador(new SolicitudHerramienta(contexto, registro, estudianteId, asignatura, cancellationToken));
155	    }
