160	    private bool EsLecturaAjena(ContextoUsuario contexto, string? estudianteId) =>
161	        estudianteId is not null
162	        && !_politicaAcceso.EvaluarLecturaEstudiante(contexto.Usuario, estudianteId, contexto.Directorio).Permitido;
