172	    private async Task<ResultadoHerramienta> ConsultarNotas(SolicitudHerramienta solicitud)
173	    {
174	        var id = solicitud.Contexto.Usuario.Id;
175	        var resumen = await ResumirAsync(id, solicitud.CancellationToken);
176	        solicitud.Registro.RegistrarReglas(ReglasAplicadas.DeNotas([resumen]));
177	        solicitud.Registro.RegistrarDatos(DatosLeidos.PorAsignatura(resumen, ProgramaDe(solicitud, id), RecursoConsultado.Notas, RecursoConsultado.Asistencia));
178	        return Responder(solicitud, FormateadorDatos.Notas(resumen), id, [RecursoConsultado.Notas, RecursoConsultado.Asistencia], Textos.SeccionNotas);
