245	        var lineas = new List<string> { FormateadorDatos.EncabezadoPrograma(programa, estudiantes.Count) };
246	        foreach (var estudiante in estudiantes)
247	        {
248	            var resumen = await ResumirAsync(estudiante.Id, solicitud.CancellationToken);
249	            resumenes.Add(resumen);
250	            lineas.Add(FormateadorDatos.LineaDePrograma(estudiante, resumen));
251	            solicitud.Registro.Registrar(estudiante.Id, [RecursoConsultado.Programa, RecursoConsultado.Notas, RecursoConsultado.Asistencia], null);
252	            solicitud.Registro.RegistrarDatos(DatosDeEstudiante(estudiante, resumen, RecursoConsultado.Programa));
253	        }
254	
255	        solicitud.Registro.RegistrarCita(new Cita(Textos.DocumentoDatosPrograma, programa.Id));
