231	        var bloques = new List<string>();
232	        var resumenes = new List<ResumenEstudiante>();
233	        foreach (var programa in solicitud.Contexto.Directorio.Programas.Where(p => programas.Contains(p.Id)))
234	        {
235	            bloques.Add(await DescribirProgramaAsync(solicitud, programa, resumenes));
236	        }
237	
238	        solicitud.Registro.RegistrarReglas(ReglasAplicadas.DePrograma(resumenes));
239	        return ResultadoHerramienta.Texto(string.Join("\n\n", bloques));
240	    }
241	
242	    private async Task<string> DescribirProgramaAsync(SolicitudHerramienta solicitud, Programa programa, List<ResumenEstudiante> resumenes)
243	    {
244	        var estudiantes = solicitud.Contexto.Directorio.Estudiantes.Where(e => e.ProgramaId == programa.Id).ToList();
245	        var lineas = new List<string> { FormateadorDatos.EncabezadoPrograma(programa, estudiantes.Count) };
246	        foreach (var estudiante in estudiantes)
247	        {
248	            var resumen = await ResumirAsync(estudiante.Id, solicitud.CancellationToken);
249	            resumenes.Add(resumen);
250	            lineas.Add(FormateadorDatos.LineaDePrograma(estudiante, resumen));
251	            solicitud.Registro.Registrar(estudiante.Id, [RecursoConsultado.Programa, RecursoConsultado.Notas, RecursoConsultado.Asistencia], null);
252	            solicitud.Registro.RegistrarDatos(DatosDeEstudiante(estudiante, resumen, RecursoConsultado.Programa));
253	        }
254	
255	        solicitud.Registro.RegistrarCita(new Cita(Textos.DocumentoDatosPrograma, programa.Id));
256	        return FormateadorDatos.Delimitar($"{Textos.DocumentoDatosPrograma} · {programa.Id}", string.Join("\n", lineas));
257	    }
258	
259	    private static string ProgramaDe(SolicitudHerramienta solicitud, string estudianteId) =>
260	        solicitud.Contexto.Directorio.Estudiantes.First(e => e.Id == estudianteId).ProgramaId;
261	
262	    private static IEnumerable<DatoConsultado> DatosDeEstudiante(Estudiante estudiante, ResumenEstudiante resumen, RecursoConsultado recursoSinAsignatura) =>
263	        DatosLeidos.PorAsignatura(resumen, estudiante.ProgramaId, RecursoConsultado.Notas, RecursoConsultado.Asistencia)
264	            .Prepend(DatosLeidos.SinAsignatura(estudiante.Id, estudiante.ProgramaId, recursoSinAsignatura));
265	
266	    private static ResultadoHerramienta Responder(
267	        SolicitudHerramienta solicitud,
268	        string contenido,
269	        string estudianteId,
270	        IEnumerable<RecursoConsultado> recursos,
271	        string seccion)
