278	    private async Task<ResumenEstudiante> ResumirAsync(string estudianteId, CancellationToken cancellationToken)
279	    {
280	        var notas = await _apiAcademica.ObtenerNotasAsync(estudianteId, cancellationToken);
281	        var asistencia = await _apiAcademica.ObtenerAsistenciaAsync(estudianteId, cancellationToken);
282	        var asignaturas = notas.Select(nota => new Asignatura(
283	            nota.Codigo,
284	            nota.Nombre,
285	            nota.Creditos,
286	            nota.Cortes,
287	            asistencia.FirstOrDefault(a => a.Codigo == nota.Codigo)?.Asistencia ?? new Asistencia(0, null))).ToList();
288	        return CalculosAcademicos.ResumirEstudiante(estudianteId, asignaturas);
