299	
300	internal sealed record AmbitoPersonal(IReadOnlySet<string> ClavesDeId, IReadOnlySet<string> ClavesDeNombre)
301	{
302	    public static AmbitoPersonal De(Usuario usuario, DirectorioAcademico directorio) => usuario.Rol switch
303	    {
304	        Rol.Coordinador => DeCoordinador(usuario, directorio),
305	        _ => DeEstudiante(usuario, directorio)
306	    };
307	
308	    public static string Clave(string idPersona) =>
309	        string.Concat(TokenizadorTexto.Valores(idPersona));
310	
311	    public static IReadOnlyList<string> ProgramasDe(Usuario usuario, DirectorioAcademico directorio) => usuario.Rol switch
312	    {
313	        Rol.Coordinador => ProgramasDeCoordinador(usuario, directorio),
314	        _ => ProgramasDeEstudiante(usuario, directorio)
315	    };
316	
317	    private static AmbitoPersonal DeEstudiante(Usuario usuario, DirectorioAcademico directorio)
318	    {
319	        var programas = ProgramasDeEstudiante(usuario, directorio);
320	        var coordinadores = directorio.Coordinadores
321	            .Where(coordinador => coordinador.ProgramasIds.Intersect(programas).Any())
322	            .Select(coordinador => Clave(coordinador.Id));
323	        var propia = Clave(usuario.Id);
324	        return new AmbitoPersonal(
325	            new HashSet<string> { propia },
326	            new HashSet<string>(coordinadores) { propia });
327	    }
328	
329	    private static AmbitoPersonal DeCoordinador(Usuario usuario, DirectorioAcademico directorio)
330	    {
331	        var programas = ProgramasDeCoordinador(usuario, directorio);
332	        var claves = directorio.Estudiantes
333	            .Where(estudiante => programas.Contains(estudiante.ProgramaId))
334	            .Select(estudiante => Clave(estudiante.Id))
335	            .Append(Clave(usuario.Id))
336	            .ToHashSet();
337	        return new AmbitoPersonal(claves, claves);
338	    }
339	
340	    private static List<string> ProgramasDeCoordinador(Usuario usuario, DirectorioAcademico directorio) =>
341	        directorio.Coordinadores
342	            .Where(coordinador => coordinador.Id == usuario.Id)
343	            .SelectMany(coordinador => coordinador.ProgramasIds)
344	            .Where(Identificadores.EsIdPrograma)
345	            .Distinct()
346	            .ToList();
347	
348	    private static List<string> ProgramasDeEstudiante(Usuario usuario, DirectorioAcademico directorio) =>
349	        directorio.Estudiantes
350	            .Where(estudiante => estudiante.Id == usuario.Id)
351	            .Select(estudiante => estudiante.ProgramaId)
352	            .Where(Identificadores.EsIdPrograma)
353	            .ToList();
354	}

