 13	
 14	public sealed record ResultadoConversacion(EstadoConversacion Estado, string? Texto, UsoTokens Uso);
 15	
 16	public sealed class ConversacionLlm
 17	{
 18	    private readonly IClienteLlm _clienteLlm;
 19	    private readonly HerramientasAsistente _herramientas;
 20	    private readonly LimitesAsistente _limites;
 21	    private readonly ConfiguracionAsistente _configuracion;
 22	
 23	    public ConversacionLlm(
 24	        IClienteLlm clienteLlm,
 25	        HerramientasAsistente herramientas,
 26	        LimitesAsistente limites,
 27	        ConfiguracionAsistente configuracion)
 28	    {
 29	        _clienteLlm = clienteLlm;
 30	        _herramientas = herramientas;
 31	        _limites = limites;
 32	        _configuracion = configuracion;
 33	    }
 34	
 35	    public async Task<ResultadoConversacion> EjecutarAsync(
 36	        ContextoUsuario contexto,
 37	        string pregunta,
 38	        IReadOnlyList<SeccionDocumento> secciones,
 39	        RegistroConsultas registro,
 40	        CancellationToken cancellationToken)
 41	    {
 42	        var estado = new Turnos(
 43	            contexto,
 44	            registro,
 45	            [ConstructorPrompts.MensajeInicial(pregunta, secciones)],
 46	            ConstructorPrompts.PromptSistema(contexto.Usuario.Rol, _configuracion.MarcadorCanario));
 47	        ResultadoConversacion? final = null;
 48	        while (final is null)
 49	        {
 50	            final = await AvanzarAsync(estado, cancellationToken);
 51	        }
 52	
 53	        return final;
 54	    }
 55	
 56	    private async Task<ResultadoConversacion?> AvanzarAsync(Turnos estado, CancellationToken cancellationToken)
 57	    {
 58	        var respuesta = await LlamarAsync(estado, cancellationToken);
 59	        estado.Uso = new UsoTokens(estado.Uso.Entrada + respuesta.Uso.Entrada, estado.Uso.Salida + respuesta.Uso.Salida);
 60	        estado.Invocaciones += respuesta.Llamadas.Count;
 61	        var terminal = Terminal(estado, respuesta);
 62	        return terminal ?? await EjecutarHerramientasAsync(estado, respuesta, cancellationToken);
 63	    }
 64	
 65	    private ResultadoConversacion? Terminal(Turnos estado, RespuestaLlm respuesta)
 66	    {
 67	        if (respuesta.Rechazada)
 68	        {
 69	            return new ResultadoConversacion(EstadoConversacion.Rechazada, null, estado.Uso);
 70	        }
 71	
 72	        if (respuesta.Llamadas.Count == 0)
 73	        {
 74	            return new ResultadoConversacion(EstadoConversacion.Completada, respuesta.Texto, estado.Uso);
 75	        }
 76	
 77	        return estado.Invocaciones > _limites.MaximoInvocacionesHerramientas
 78	            ? new ResultadoConversacion(EstadoConversacion.LimiteHerramientas, null, estado.Uso)
 79	            : null;
 80	    }
 81	
 82	    private async Task<ResultadoConversacion?> EjecutarHerramientasAsync(Turnos estado, RespuestaLlm respuesta, CancellationToken cancellationToken)
 83	    {
 84	        estado.Mensajes.Add(new MensajeLlm(RolMensaje.Asistente, respuesta.Texto ?? string.Empty, null, respuesta.Llamadas));
 85	        foreach (var llamada in respuesta.Llamadas)
 86	        {
 87	            var resultado = await _herramientas.EjecutarAsync(llamada, estado.Contexto, estado.Registro, cancellationToken);
 88	            if (resultado.IdAjeno)
 89	            {
 90	                return new ResultadoConversacion(EstadoConversacion.IdAjeno, null, estado.Uso);
 91	            }
 92	
 93	            estado.Registro.AgregarFuente(resultado.Contenido);
 94	            estado.Mensajes.Add(new MensajeLlm(RolMensaje.Herramienta, resultado.Contenido, llamada.Id, []));
 95	        }
 96	
 97	        return null;
 98	    }
 99	
100	    private async Task<RespuestaLlm> LlamarAsync(Turnos estado, CancellationToken cancellationToken)
101	    {
102	        var solicitud = new SolicitudLlm(
103	            estado.PromptSistema,
104	            [.. estado.Mensajes],
105	            HerramientasAsistente.Definir(estado.Contexto.Usuario.Rol),
106	            _limites.MaximoTokensSalida);
107	        using var limite = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
108	        limite.CancelAfter(TimeSpan.FromSeconds(_limites.TimeoutLlmSegundos));
109	        try
110	        {
111	            return await _clienteLlm.CompletarAsync(solicitud, limite.Token);
112	        }
113	        catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
114	        {
115	            throw new DependenciaNoDisponibleException("El proveedor del LLM no respondió a tiempo.");
116	        }
117	    }
118	
119	    private sealed class Turnos(ContextoUsuario contexto, RegistroConsultas registro, List<MensajeLlm> mensajes, string promptSistema)
120	    {
121	        public ContextoUsuario Contexto { get; } = contexto;
122	
123	        public RegistroConsultas Registro { get; } = registro;
124	
125	        public List<MensajeLlm> Mensajes { get; } = mensajes;
126	
127	        public string PromptSistema { get; } = promptSistema;
128	
129	        public UsoTokens Uso { get; set; } = new(0, 0);
130	
131	        public int Invocaciones { get; set; }
132	    }
133	}
