138	public static class ArgumentosHerramienta
139	{
140	    public static string? LeerTexto(string argumentosJson, string nombre)
141	    {
142	        try
143	        {
144	            using var documento = JsonDocument.Parse(argumentosJson);
145	            return Extraer(documento.RootElement, nombre);
146	        }
147	        catch (JsonException)
148	        {
149	            return null;
150	        }
151	    }
152	
153	    private static string? Extraer(JsonElement raiz, string nombre)
154	    {
155	        if (raiz.ValueKind != JsonValueKind.Object || !raiz.TryGetProperty(nombre, out var valor))
156	        {
157	            return null;
158	        }
159	
160	        return valor.ValueKind == JsonValueKind.String ? valor.GetString() ?? string.Empty : valor.ToString();
161	    }
162	}
