227	public sealed record SalidaVerificada(string Respuesta, IReadOnlyList<Cita> Citas, ResultadoAuditoria Resultado);
228	
229	public sealed partial class VerificadorSalida
230	{
231	    private const string DocumentoDerogado = "reglamento_academico_2023.md";
232	
233	    private readonly HashSet<string> _documentosDerogados = new HashSet<string> { DocumentoDerogado };
234	    private readonly Regex _numero = Numero();
235	    private readonly Regex _notaOPorcentaje = NotaOPorcentaje();
236	    private readonly Func<string, string> _normalizar = NormalizadorTexto.Normalizar;
237	
238	    public SalidaVerificada Verificar(
239	        Usuario usuario,
240	        string respuesta,
241	        IReadOnlyList<Cita> citas,
242	        IReadOnlyCollection<string> idsPersonasAutorizadas,
243	        IReadOnlyCollection<string> textosFuente,
244	        IBaseConocimiento baseConocimiento,
245	        DirectorioAcademico directorio)
246	    {
247	        if (ContienePersonaNoAutorizada(respuesta, idsPersonasAutorizadas, directorio))
248	        {
249	            return new SalidaVerificada(Textos.Negativa(usuario.Rol), [Textos.CitaNegativa()], ResultadoAuditoria.FugaBloqueada);
250	        }
251	
252	        if (!TodosLosNumerosSonVerificables(respuesta, textosFuente))
253	        {
254	            return new SalidaVerificada(Textos.NoVerificable, [], ResultadoAuditoria.NumeroNoVerificado);
255	        }
256	
257	        return new SalidaVerificada(respuesta, DescartarCitasInexistentes(citas, baseConocimiento), ResultadoAuditoria.Respondida);
258	    }
259	
260	    public IReadOnlyList<Cita> DescartarCitasInexistentes(IReadOnlyList<Cita> citas, IBaseConocimiento baseConocimiento) =>
261	        citas.Where(cita => !_documentosDerogados.Contains(cita.Documento) && baseConocimiento.ExisteCita(cita)).ToList();
262	
263	    public bool ContienePersonaNoAutorizada(string respuesta, IReadOnlyCollection<string> idsPersonasAutorizadas, DirectorioAcademico directorio) =>
264	        DetectorTerceros.PersonasMencionadas(_normalizar(respuesta), directorio)
265	            .Any(id => !idsPersonasAutorizadas.Contains(id));
266	
267	    public bool TodosLosNumerosSonVerificables(string respuesta, IReadOnlyCollection<string> textosFuente)
268	    {
269	        var numerosDeFuentes = textosFuente
270	            .SelectMany(texto => _numero.Matches(texto).Select(coincidencia => coincidencia.Value))
271	            .ToHashSet();
272	        return NumerosAVerificar(respuesta).All(numerosDeFuentes.Contains);
273	    }
274	
275	    private IEnumerable<string> NumerosAVerificar(string respuesta) =>
276	        _notaOPorcentaje.Matches(respuesta)
277	            .Select(coincidencia => coincidencia.Groups["numero"].Value);
278	
279	    [GeneratedRegex(@"(?<![0-9.])[0-9]+(\.[0-9]+)?")]
280	    private static partial Regex Numero();
281	
282	    [GeneratedRegex(@"(?<![0-9.])(?<numero>[0-9]\.[0-9]{1,2})(?![0-9])|(?<![0-9.])(?<numero>[0-9]+(\.[0-9]+)?)(?=\s*%)")]
283	    private static partial Regex NotaOPorcentaje();
284	}

