128	    private const string CaracteresIgnorables = "​‌‍⁠﻿­";
129	
130	    private static readonly IReadOnlyDictionary<char, char> SinAcento = ConstruirTablaSinAcento(
131	        ('a', "áàäâãåāăą"),
