140	    public static IReadOnlyList<TokenTexto> Tokenizar(string texto)
141	    {
142	        var acumulador = new AcumuladorTokens();
143	        for (var indice = 0; indice < texto.Length; indice++)
144	        {
145	            Procesar(acumulador, texto[indice], indice);
