279	            .Any(programa => Menciona(tokens, programa.Id) || Menciona(tokens, programa.Nombre));
280	    }
281	
282	    private static bool Menciona(IReadOnlyList<TokenTexto> tokens, string texto) =>
283	        TokenizadorTexto.BuscarSecuencia(tokens, TokenizadorTexto.Valores(texto)) >= 0;
284	}

