206	        configuracion["LLM_URL_BASE"],
207	        configuracion["LLM_MODELO"],
208	        LeerDecimal(configuracion["LLM_PRECIO_ENTRADA"]),
209	        LeerDecimal(configuracion["LLM_PRECIO_SALIDA"]));
