217	        var precio = resuelto.PrecioDesconocido ? null : new PrecioModelo(resuelto.PrecioEntradaPorMillon, resuelto.PrecioSalidaPorMillon);
218	        var codigos = configuracion.GetSection(SeccionCodigosAsignatura).Get<string[]>() ?? [];
219	        return new ConfiguracionAsistente(precio, configuracion[ClaveMarcadorCanario], codigos);
220	    }
