224	public static class EncabezadosDeSeguridad
225	{
226	    private static readonly (string Nombre, string Valor)[] Encabezados =
227	    [
228	        ("X-Content-Type-Options", "nosniff"),
229	        ("X-Frame-Options", "DENY"),
230	        ("Referrer-Policy", "no-referrer")
231	    ];
