233	    public static IApplicationBuilder UsarEncabezadosDeSeguridad(this IApplicationBuilder aplicacion) =>
234	        aplicacion.Use(async (contexto, siguiente) =>
235	        {
236	            contexto.Response.OnStarting(() =>
237	            {
238	                foreach (var (nombre, valor) in Encabezados)
239	                {
240	                    contexto.Response.Headers[nombre] = valor;
241	                }
242	
243	                return Task.CompletedTask;
244	            });
245	            await siguiente();
246	        });
247	}
