285	namespace TutorFlow.Api;
286	
287	public sealed record ResultadoTasa(bool Permitido, int SegundosParaReintentar);
288	
289	public sealed class LimitadorTasaPorIp
290	{
291	    private const int UmbralDeLimpieza = 10_000;
292	
293	    private readonly ConcurrentDictionary<string, Queue<DateTimeOffset>> _porIp = new();
294	    private readonly int _limite;
295	    private readonly TimeSpan _ventana;
296	    private readonly TimeProvider _tiempo;
297	
298	    public LimitadorTasaPorIp(int limite, TimeSpan ventana, TimeProvider tiempo)
299	    {
300	        _limite = limite;
301	        _ventana = ventana;
302	        _tiempo = tiempo;
303	    }
304	
305	    public ResultadoTasa Intentar(string ip)
306	    {
307	        var ahora = _tiempo.GetUtcNow();
308	        LimpiarSiHaceFalta(ahora);
309	        var cola = _porIp.GetOrAdd(ip, _ => new Queue<DateTimeOffset>());
310	        lock (cola)
311	        {
312	            Purgar(cola, ahora);
313	            if (cola.Count < _limite)
314	            {
315	                cola.Enqueue(ahora);
316	                return new ResultadoTasa(true, 0);
317	            }
318	
319	            return new ResultadoTasa(false, SegundosHastaLiberar(cola.Peek(), ahora));
320	        }
321	    }
322	
323	    private int SegundosHastaLiberar(DateTimeOffset masAntigua, DateTimeOffset ahora) =>
324	        Math.Max(1, (int)Math.Ceiling((masAntigua + _ventana - ahora).TotalSeconds));
325	
326	    private void Purgar(Queue<DateTimeOffset> cola, DateTimeOffset ahora)
327	    {
328	        while (cola.Count > 0 && ahora - cola.Peek() >= _ventana)
329	        {
330	            cola.Dequeue();
331	        }
332	    }
333	
334	    private void LimpiarSiHaceFalta(DateTimeOffset ahora)
335	    {
336	        if (_porIp.Count < UmbralDeLimpieza)
337	        {
338	            return;
339	        }
340	
341	        foreach (var (ip, cola) in _porIp)
342	        {
343	            lock (cola)
344	            {
345	                Purgar(cola, ahora);
346	                if (cola.Count == 0)
347	                {
348	                    _porIp.TryRemove(ip, out _);
349	                }
350	            }
351	        }
352	    }
353	}

