    42	            return await operacion(limite.Token);
    43	        }
    44	        catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
    45	        {
    46	            throw new DependenciaNoDisponibleException("Se agotó el presupuesto de tiempo de la API académica.");
    47	        }
    48	        finally
    49	        {
    50	            var restante = _restante - cronometro.Elapsed;
    51	            _restante = restante > TimeSpan.Zero ? restante : TimeSpan.Zero;
    52	        }
