    97	namespace TutorFlow.Infrastructure.Llm;
    98	
    99	public sealed class ClienteLlmCompatibleOpenAi : IClienteLlm
   100	{
   101	    private const string LlaveParaServidoresSinAutenticacion = "sin-llave";
   102	    private const string SegmentoDeVersion = "v1/";
   103	    private const int ReintentosMaximos = 0;
   104	
   105	    private readonly IChatClient _cliente;
   106	    private readonly string _modelo;
   107	
   108	    public ClienteLlmCompatibleOpenAi(HttpClient httpClient, ProveedorResuelto proveedor, string? llave)
   109	    {
   110	        _modelo = proveedor.Modelo;
   111	        var opciones = new OpenAIClientOptions
   112	        {
   113	            Endpoint = ConstruirEndpoint(proveedor.UrlBase),
   114	            Transport = new HttpClientPipelineTransport(httpClient),
   115	            RetryPolicy = new ClientRetryPolicy(ReintentosMaximos)
   116	        };
   117	        var credencial = new ApiKeyCredential(string.IsNullOrWhiteSpace(llave) ? LlaveParaServidoresSinAutenticacion : llave);
   118	        _cliente = new OpenAIClient(credencial, opciones).GetChatClient(proveedor.Modelo).AsIChatClient();
   119	    }
   120	
   121	    public async Task<RespuestaLlm> CompletarAsync(SolicitudLlm solicitud, CancellationToken cancellationToken)
   122	    {
   123	        var opciones = new ChatOptions
   124	        {
   125	            ModelId = _modelo,
   126	            MaxOutputTokens = solicitud.MaximoTokensSalida,
   127	            Tools = [.. solicitud.Herramientas.Select(Declarar)]
   128	        };
   129	        try
   130	        {
   131	            var respuesta = await _cliente.GetResponseAsync(Mensajes(solicitud), opciones, cancellationToken);
   132	            return Traducir(respuesta);
   133	        }
   134	        catch (ClientResultException)
   135	        {
   136	            throw new DependenciaNoDisponibleException("El proveedor del LLM respondió con un error.");
   137	        }
   138	    }
   139	
   140	    private static Uri ConstruirEndpoint(string urlBase)
   141	    {
   142	        var raiz = new Uri(urlBase.TrimEnd('/') + "/");
   143	        return raiz.AbsolutePath == "/" ? new Uri(raiz, SegmentoDeVersion) : raiz;
   144	    }
   145	
   146	    private static List<ChatMessage> Mensajes(SolicitudLlm solicitud)
   147	    {
   148	        var mensajes = new List<ChatMessage> { new(ChatRole.System, solicitud.PromptSistema) };
   149	        mensajes.AddRange(solicitud.Mensajes.Select(Mensaje));
   150	        return mensajes;
   151	    }
   152	
   153	    private static ChatMessage Mensaje(MensajeLlm mensaje) => mensaje.Rol switch
   154	    {
   155	        RolMensaje.Herramienta => new ChatMessage(ChatRole.Tool, [new FunctionResultContent(mensaje.IdLlamada ?? string.Empty, mensaje.Contenido)]),
   156	        RolMensaje.Asistente => MensajeDeAsistente(mensaje),
   157	        _ => new ChatMessage(ChatRole.User, mensaje.Contenido)
   158	    };
   159	
   160	    private static ChatMessage MensajeDeAsistente(MensajeLlm mensaje)
   161	    {
   162	        var contenidos = new List<AIContent>();
   163	        if (!string.IsNullOrEmpty(mensaje.Contenido))
   164	        {
   165	            contenidos.Add(new TextContent(mensaje.Contenido));
   166	        }
   167	
   168	        contenidos.AddRange(mensaje.Llamadas.Select(llamada =>
   169	            new FunctionCallContent(llamada.Id, llamada.Nombre, ArgumentosDe(llamada.ArgumentosJson))));
   170	        return new ChatMessage(ChatRole.Assistant, contenidos);
   171	    }
   172	
   173	    private static Dictionary<string, object?> ArgumentosDe(string argumentosJson)
   174	    {
   175	        using var documento = JsonDocument.Parse(argumentosJson);
   176	        return documento.RootElement.ValueKind == JsonValueKind.Object
   177	            ? documento.RootElement.EnumerateObject().ToDictionary(p => p.Name, p => (object?)p.Value.Clone())
   178	            : [];
   179	    }
   180	
   181	    private static AIFunctionDeclaration Declarar(HerramientaLlm herramienta)
   182	    {
   183	        var propiedades = herramienta.Parametros.ToDictionary(
   184	            parametro => parametro.Nombre,
   185	            parametro => new { type = "string", description = parametro.Descripcion });
   186	        var esquema = JsonSerializer.SerializeToElement(new
   187	        {
   188	            type = "object",
   189	            properties = propiedades,
   190	            required = herramienta.Parametros.Where(p => p.Requerido).Select(p => p.Nombre).ToArray()
   191	        });
   192	        return AIFunctionFactory.CreateDeclaration(herramienta.Nombre, herramienta.Descripcion, esquema);
   193	    }
   194	
   195	    private static RespuestaLlm Traducir(ChatResponse respuesta)
   196	    {
   197	        var rechazada = EsRechazo(respuesta);
   198	        var texto = rechazada ? null : respuesta.Text;
   199	        return new RespuestaLlm(
   200	            string.IsNullOrEmpty(texto) ? null : texto,
   201	            LlamadasDe(respuesta),
   202	            UsoDe(respuesta.Usage),
   203	            rechazada);
   204	    }
   205	
   206	    private static bool EsRechazo(ChatResponse respuesta) =>
   207	        respuesta.FinishReason == ChatFinishReason.ContentFilter
   208	        || (respuesta.RawRepresentation is OpenAI.Chat.ChatCompletion completado && !string.IsNullOrEmpty(completado.Refusal));
   209	
   210	    private static List<LlamadaHerramienta> LlamadasDe(ChatResponse respuesta) =>
   211	        [.. respuesta.Messages
   212	            .SelectMany(mensaje => mensaje.Contents)
   213	            .OfType<FunctionCallContent>()
   214	            .Select(llamada => new LlamadaHerramienta(llamada.CallId, llamada.Name, JsonSerializer.Serialize(llamada.Arguments ?? new Dictionary<string, object?>())))];
   215	
   216	    private static UsoTokens UsoDe(UsageDetails? uso) =>
   217	        new((int)(uso?.InputTokenCount ?? 0), (int)(uso?.OutputTokenCount ?? 0));
   218	}
