   221	public sealed class PresupuestoDiario
   222	{
   223	    private readonly Lock _candado = new();
   224	    private readonly IReloj _reloj;
   225	    private readonly LimitesAsistente _limites;
   226	    private DateOnly _dia;
   227	    private decimal _gastado;
   228	
   229	    public PresupuestoDiario(IReloj reloj, LimitesAsistente limites)
   230	    {
   231	        _reloj = reloj;
   232	        _limites = limites;
   233	        _dia = DiaActual();
   234	    }
   235	
   236	    public bool Agotado
   237	    {
   238	        get
   239	        {
   240	            lock (_candado)
   241	            {
   242	                ReiniciarSiCambioElDia();
   243	                return _gastado >= _limites.PresupuestoDiarioUsd;
   244	            }
   245	        }
   246	    }
   247	
   248	    public void Registrar(decimal costoUsd)
   249	    {
   250	        lock (_candado)
   251	        {
   252	            ReiniciarSiCambioElDia();
   253	            _gastado += costoUsd;
   254	        }
   255	    }
   256	
   257	    private DateOnly DiaActual() => DateOnly.FromDateTime(_reloj.AhoraUtc.UtcDateTime);
   258	
   259	    private void ReiniciarSiCambioElDia()
   260	    {
   261	        var hoy = DiaActual();
   262	        if (hoy == _dia)
   263	        {
   264	            return;
   265	        }
   266	
   267	        _dia = hoy;
   268	        _gastado = 0m;
   269	    }
   270	}
   271	namespace TutorFlow.Core.Asistente;
   272	
   273	public sealed record ResultadoIdentidades(bool Superado, bool SuperacionNueva, IReadOnlyList<string> Ids);
   274	
   275	public sealed class LimitadorIdentidades
   276	{
   277	    private const int UmbralDeLimpieza = 10_000;
   278	
   279	    private readonly Lock _candado = new();
   280	    private readonly Dictionary<string, List<(DateTimeOffset Momento, string Id)>> _porIp = [];
   281	    private readonly IReloj _reloj;
   282	    private readonly LimitesAsistente _limites;
   283	
   284	    public LimitadorIdentidades(IReloj reloj, LimitesAsistente limites)
   285	    {
   286	        _reloj = reloj;
   287	        _limites = limites;
   288	    }
   289	
   290	    private TimeSpan Ventana => TimeSpan.FromMinutes(_limites.VentanaIdentidadesMinutos);
   291	
   292	    public ResultadoIdentidades Registrar(string ipOrigen, string usuarioId)
   293	    {
   294	        lock (_candado)
   295	        {
   296	            var ahora = _reloj.AhoraUtc;
   297	            LimpiarSiHaceFalta(ahora);
   298	            var entradas = ObtenerVigentes(ipOrigen, ahora);
   299	            var antes = entradas.Select(e => e.Id).Distinct().Count();
   300	            entradas.Add((ahora, usuarioId));
   301	            var ids = entradas.Select(e => e.Id).Distinct().ToList();
   302	            var superado = ids.Count > _limites.MaximoIdentidadesPorIp;
   303	            return new ResultadoIdentidades(superado, superado && antes <= _limites.MaximoIdentidadesPorIp, ids);
   304	        }
   305	    }
   306	
   307	    private List<(DateTimeOffset Momento, string Id)> ObtenerVigentes(string ipOrigen, DateTimeOffset ahora)
   308	    {
   309	        if (!_porIp.TryGetValue(ipOrigen, out var entradas))
   310	        {
   311	            entradas = [];
   312	            _porIp[ipOrigen] = entradas;
   313	        }
   314	
   315	        entradas.RemoveAll(e => ahora - e.Momento > Ventana);
   316	        return entradas;
   317	    }
   318	
   319	    private void LimpiarSiHaceFalta(DateTimeOffset ahora)
   320	    {
   321	        if (_porIp.Count < UmbralDeLimpieza)
   322	        {
   323	            return;
   324	        }
   325	
   326	        foreach (var ip in _porIp.Keys.ToList())
   327	        {
   328	            _porIp[ip].RemoveAll(e => ahora - e.Momento > Ventana);
   329	            if (_porIp[ip].Count == 0)
   330	            {
   331	                _porIp.Remove(ip);
   332	            }
   333	        }
   334	    }
   335	}
