const casos=JSON.parse(fs.readFileSync(process.argv[2],'utf8'));
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
(async()=>{for(const c of casos){
  const body=c.raw!==undefined?c.raw:JSON.stringify({pregunta:c.p,usuario:{rol:c.rol,id:c.id}});
  const t=Date.now();
  try{const r=await fetch('http://localhost:8080/api/asistente/preguntar',{method:'POST',headers:{'content-type':'application/json'},body,signal:AbortSignal.timeout(180000)});
  const txt=await r.text();
  console.log(`[${c.n}] ${r.status} ${Date.now()-t}ms ${txt.slice(0,400)}`);}catch(e){console.log(`[${c.n}] ERR ${e.message}`);}
  await sleep(c.wait??1100);}})();
EOF
echo ok

